import{_ as s,c as i,o as t,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"ADDRESSING RISKS FROM SUSMAN GODFREY","description":"","frontmatter":{"title":"ADDRESSING RISKS FROM SUSMAN GODFREY","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/addressing-risks-from-susman-godfrey/","publishDate":"2025-04-09T19:22:15-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-09-addressing-risks-from-susman-godfrey.md","filePath":"executive-orders/2025-04-09-addressing-risks-from-susman-godfrey.md"}'),a={name:"executive-orders/2025-04-09-addressing-risks-from-susman-godfrey.md"};function r(o,e,d,l,c,u){return t(),i("div",null,e[0]||(e[0]=[n('<h1 id="addressing-risks-from-susman-godfrey" tabindex="-1">ADDRESSING RISKS FROM SUSMAN GODFREY <a class="header-anchor" href="#addressing-risks-from-susman-godfrey" aria-label="Permalink to &quot;ADDRESSING RISKS FROM SUSMAN GODFREY&quot;">​</a></h1><p>Published: Wednesday, April 9, 2025</p><ul><li>The executive order asserts that lawyers and law firms undermining critical American interests should be denied access to national secrets and federal funds.</li><li>It identifies Susman Godfrey LLP (Susman) as engaging in activities harmful to American interests, including: <ul><li>Weaponizing the legal system against American elections.</li><li>Funding groups that undermine the U.S. military with political ideologies.</li><li>Discriminating based on race through financial awards and employment programs for &quot;students of color.&quot;</li></ul></li><li>The order mandates steps to suspend security clearances for individuals at Susman pending a national interest review.</li><li>The Office of Management and Budget is tasked with identifying and ceasing government support for Susman.</li><li>Government contracting agencies must disclose any business with Susman in contracts, focusing on preventing taxpayer funds from supporting discriminatory practices.</li><li>Agencies are to review and potentially terminate contracts with Susman and align funding decisions with U.S. interests and the goals of the Administration.</li><li>Agencies will limit access to government buildings for Susman employees and restrict employee engagement unless a national security waiver is granted.</li><li>The order clarifies it does not restrict the authority of executive departments or other legal statutes, is subject to legal limitations, and does not create enforceable rights against the U.S. government.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/addressing-risks-from-susman-godfrey/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/addressing-risks-from-susman-godfrey/</a></p>',4)]))}const f=s(a,[["render",r]]);export{g as __pageData,f as default};
